@mixin flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

:host {
  .story-avatar {
    @flex-center;
    width: 56px;
  }
}

@use 'colors' as c;

:host {
  .follow-btn {
    background: colors.$primary;
    color: c.$white;
  }
}

$icons: like, comment, share;

:host {
  @each $icon in $icons {
    .icon-$icon {
      background-image: url('/assets/#{$icon}.svg');
    }
  }
}

$icons: like, comment, share;

:host {
  @each $icon in $icons {
    .icon-#{$icon} {
      background-image: url('/assets/#{$icon}.svg');
    }
  }
}
